/**
 * Maps each block type to a component and type-checks the mapping. `defineBlocks<MoteurSchema>({ hero: Hero, … })`
 * fails `astro check` when a block type has no component or when a component's props do not match the block's data.
 */
import type { SchemaShape } from '@moteurio/client';

/** A block as the API delivers it. */
export type AnyBlock = { type: string; data: unknown };

/** The project's blocks in a single language, taken from the types generated by `moteur types`. */
type BlocksOf<S extends SchemaShape> = S['one'] extends {
    blocks: infer B extends AnyBlock;
}
    ? B
    : AnyBlock;

/**
 * The props of a block component: the block's data, the block itself, and the values the page
 * shares with every block (`shared` on `<Blocks>`, for example the page's URL or the site's texts).
 */
export type BlockProps<B extends AnyBlock, Shared = {}> = { data: B['data']; block: B } & Shared;

/** An Astro component, or any function component, that renders a block. */
export type BlockComponent<B extends AnyBlock, Shared = {}> = (
    props: BlockProps<B, Shared>
) => unknown;

/**
 * A component for every block type the content can contain, keyed by block type. The project's own
 * blocks use their plain name (`hero`) and the server's built-in blocks use their namespace (`core/quote`).
 */
export type BlockComponents<S extends SchemaShape, Shared = {}> = {
    [B in BlocksOf<S> as B['type']]: BlockComponent<B, Shared>;
};

export interface DefinedBlocks<Shared = {}> {
    /** Returns the component for this block, or undefined for a block type that has no component in the site. */
    for(block: AnyBlock): BlockComponent<AnyBlock, Shared> | undefined;
}

const warned = new Set<string>();
const inDev = () =>
    (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env
        ?.NODE_ENV !== 'production';

/**
 * Defines the components for all block types. `Shared` is the type of the values that every block
 * also receives from the page, passed once as `<Blocks shared={…}>`. A component may use any part of
 * `Shared`, and one that requires more than the page shares fails `astro check`.
 */
export function defineBlocks<S extends SchemaShape, Shared = {}>(
    components: BlockComponents<S, Shared>
): DefinedBlocks<Shared> {
    const map = components as unknown as Record<string, BlockComponent<AnyBlock, Shared>>;
    return {
        for(block) {
            const type = block.type;
            const found = map[type];
            if (!found && inDev() && !warned.has(type)) {
                // Skip block types that have no component in the site yet instead of failing the build.
                warned.add(type);
                console.warn(`[moteur] No component for block "${type}": it is skipped.`);
            }
            return found;
        }
    };
}
